import type { ReactNode } from "react";
import Footer from "~/components/Footer/Footer";
import Header from "~/components/Header/Header";
import "./PageLayout.css";
interface PageShellProps {
  children: ReactNode;
  className?: string;
  showHeader?: boolean;
  showFooter?: boolean;
}

interface PageHeaderProps {
  badge: string;
  title: ReactNode;
  description: ReactNode;
  children?: ReactNode;
  className?: string;
}

interface PageCTAProps {
  title: ReactNode;
  description?: ReactNode;
  eyebrow?: string;
  children: ReactNode;
  className?: string;
}

export function PageShell({
  children,
  className = "",
  showHeader = true,
  showFooter = true,
}: PageShellProps) {
  return (
    <section className={`app-section page-shell ${className}`.trim()}>
      {showHeader && <Header float />}
      {children}
      {showFooter && <Footer />}
    </section>
  );
}

export function PageHeader({
  badge,
  title,
  description,
  children,
  className = "",
}: PageHeaderProps) {
  return (
    <header className={`page-header ${className}`.trim()}>
      <span className="page-badge">{badge}</span>
      <h1 className="page-title">{title}</h1>
      <p className="page-subtitle">{description}</p>
      {children}
    </header>
  );
}

export function PageCTA({ title, description, eyebrow, children, className = "" }: PageCTAProps) {
  return (
    <aside className={`page-cta glass-panel ${className}`.trim()}>
      <div className="page-cta-content">
        {eyebrow && <p className="page-eyebrow">{eyebrow}</p>}
        <h2 className="page-cta-title">{title}</h2>
        {description && <p className="page-cta-description">{description}</p>}
      </div>
      <div className="page-actions">{children}</div>
    </aside>
  );
}
